// propHex normalises "#abc", "abc" or "#AABBCC" to "#aabbcc", or returns "#000000".
func propHex(v string) string {
	if len(v) > 0 && v[0] == '#' {
		v = v[1:]
	}
	if len(v) == 3 {
		v = string([]byte{v[0], v[0], v[1], v[1], v[2], v[2]})
	}
	if len(v) != 6 {
		return "#000000"
	}
	out := make([]byte, 6)
	for i := 0; i < 6; i++ {
		c := v[i]
		switch {
		case c >= '0' && c <= '9', c >= 'a' && c <= 'f':
			out[i] = c
		case c >= 'A' && c <= 'F':
			out[i] = c + 32
		default:
			return "#000000"
		}
	}
	return "#" + string(out)
}

